package com.bank.diskguard;

import java.util.*;
import java.util.logging.*;

public class BrokerDiskGuardDemo {
    private static final Logger log = Logger.getLogger(BrokerDiskGuardDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DiskGuard guard = new DiskGuard(0.70, 0.90);

        // A broker that fills up over time.
        for (double used : new double[]{0.55, 0.75, 0.92, 1.00}) {
            BrokerDiskState state = new BrokerDiskState("broker-2", used);
            String status = guard.classify(state);
            boolean writable = guard.acceptsWrites(state);
            log.info(() -> String.format("broker-2 disk %.0f%% → %s | writes %s",
                    used * 100, status, writable ? "ACCEPTED" : "REJECTED"));
            if (!writable) {
                // Follower on a full broker drops out of ISR, reducing redundancy.
                log.warning("Follower on broker-2 fell out of ISR for transactions partitions");
                log.severe("RECOVERY: reduce retention.ms, add disk/brokers, reassign partitions "
                         + "(do NOT hand-delete segment files)");
            }
        }
    }
}

