class BrokerDiskState {
    private final String brokerId;
    private final double usedFraction;   // 0.0 .. 1.0
    BrokerDiskState(String brokerId, double usedFraction) {
        if (usedFraction < 0 || usedFraction > 1)
            throw new IllegalArgumentException("usedFraction must be 0..1");
            this.brokerId = brokerId;
            this.usedFraction = usedFraction;
    }
    String getBrokerId() { return brokerId; }
    double getUsedFraction() { return usedFraction; }
}

// ─── Would be in service/DiskGuard.java in a real project ───
class DiskGuard {
    private final double warn;
    private final double critical;
        DiskGuard(double warn, double critical) { this.warn = warn;
        this.critical = critical; }

    String classify(BrokerDiskState s) {
        double u = s.getUsedFraction();
        if (u >= 1.0) return "FULL (log dir offline, partitions unavailable for writes)";
        if (u >= critical) return "CRITICAL (act now)";
        if (u >= warn) return "WARNING (clean up / add capacity soon)";
        return "HEALTHY";
    }

    // Once the disk is full, the log directory goes offline → writes rejected.
    boolean acceptsWrites(BrokerDiskState s) {
        return s.getUsedFraction() < 1.0;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
